package v1alpha1

// CRD drift guard.
//
// The CRD YAMLs under config/crd/bases are hand-written, not generated by
// controller-gen. Two failure modes have no other safety net:
//
//  1. A field added to a Go *_types.go struct but not to the CRD schema.
//     The API server's structural-schema pruning silently DROPS it on every
//     write — the operator sees zero values and nothing errors.
//  2. A list declared x-kubernetes-list-type=map whose key isn't required
//     in the item schema. The API server rejects the whole CRD (this has bitten us).
//
// This test walks every CRD schema alongside the Go type it mirrors and
// fails on both. It runs in `make ci` with the rest of the operator tests.

import (
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"

	"sigs.k8s.io/yaml"
)

const crdDir = "../../config/crd/bases"

// crdKinds maps each CRD kind to its Go Spec + Status types.
var crdKinds = map[string][2]reflect.Type{
	"Model":       {reflect.TypeOf(ModelSpec{}), reflect.TypeOf(ModelStatus{})},
	"Skill":       {reflect.TypeOf(SkillSpec{}), reflect.TypeOf(SkillStatus{})},
	"Agent":       {reflect.TypeOf(AgentSpec{}), reflect.TypeOf(AgentStatus{})},
	"DLPPolicy":   {reflect.TypeOf(DLPPolicySpec{}), reflect.TypeOf(DLPPolicyStatus{})},
	"AccessGrant": {reflect.TypeOf(AccessGrantSpec{}), reflect.TypeOf(AccessGrantStatus{})},
}

type schemaNode = map[string]interface{}

func loadCRDSchemas(t *testing.T) map[string]schemaNode {
	t.Helper()
	files, err := filepath.Glob(filepath.Join(crdDir, "*.yaml"))
	if err != nil || len(files) == 0 {
		t.Fatalf("no CRD files in %s (err=%v)", crdDir, err)
	}
	out := map[string]schemaNode{}
	for _, f := range files {
		body, err := os.ReadFile(f)
		if err != nil {
			t.Fatalf("read %s: %v", f, err)
		}
		var crd struct {
			Spec struct {
				Names    struct{ Kind string } `json:"names"`
				Versions []struct {
					Schema struct {
						OpenAPIV3Schema schemaNode `json:"openAPIV3Schema"`
					} `json:"schema"`
				} `json:"versions"`
			} `json:"spec"`
		}
		if err := yaml.Unmarshal(body, &crd); err != nil {
			t.Fatalf("parse %s: %v", f, err)
		}
		if len(crd.Spec.Versions) == 0 {
			t.Fatalf("%s: no versions", f)
		}
		out[crd.Spec.Names.Kind] = crd.Spec.Versions[0].Schema.OpenAPIV3Schema
	}
	return out
}

func props(n schemaNode) schemaNode {
	p, _ := n["properties"].(map[string]interface{})
	return p
}

// jsonFields returns json-tag name → field type for a struct type.
func jsonFields(t reflect.Type) map[string]reflect.Type {
	out := map[string]reflect.Type{}
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		name := strings.Split(f.Tag.Get("json"), ",")[0]
		if name == "" || name == "-" {
			continue
		}
		out[name] = f.Type
	}
	return out
}

// elem unwraps pointers and slices to the underlying named type.
func elem(t reflect.Type) reflect.Type {
	for t.Kind() == reflect.Ptr || t.Kind() == reflect.Slice {
		t = t.Elem()
	}
	return t
}

var ownPkg = reflect.TypeOf(ModelSpec{}).PkgPath()

// walk compares one Go struct with one schema node, recursing into
// structs defined in this package. Types from other packages
// (corev1.ResourceRequirements, metav1.Condition, …) are trusted — the CRD
// either preserves unknown fields for them or spells them out by hand.
func walk(path string, goType reflect.Type, node schemaNode, problems *[]string) {
	if node == nil {
		return
	}
	if preserve, _ := node["x-kubernetes-preserve-unknown-fields"].(bool); preserve {
		return
	}
	goType = elem(goType)
	if goType.Kind() != reflect.Struct || goType.PkgPath() != ownPkg {
		return
	}
	p := props(node)
	fields := jsonFields(goType)
	for name, ft := range fields {
		sub, ok := p[name].(map[string]interface{})
		if !ok {
			*problems = append(*problems, path+"."+name+": in Go type, missing from CRD schema (the API server will silently prune it)")
			continue
		}
		if sub["type"] == "array" {
			items, _ := sub["items"].(map[string]interface{})
			sub = items
		}
		walk(path+"."+name, ft, sub, problems)
	}
	for name := range p {
		if _, ok := fields[name]; !ok {
			*problems = append(*problems, path+"."+name+": in CRD schema, no matching Go field")
		}
	}
}

// listMapKeyProblems finds x-kubernetes-list-type=map lists whose keys
// aren't in the item schema's `required` list (API server rejects these).
func listMapKeyProblems(path string, node schemaNode, problems *[]string) {
	if node == nil {
		return
	}
	if node["x-kubernetes-list-type"] == "map" {
		items, _ := node["items"].(map[string]interface{})
		req := map[string]bool{}
		if r, ok := items["required"].([]interface{}); ok {
			for _, k := range r {
				req[k.(string)] = true
			}
		}
		if keys, ok := node["x-kubernetes-list-map-keys"].([]interface{}); ok {
			for _, k := range keys {
				if !req[k.(string)] {
					*problems = append(*problems, path+": list-map-key "+k.(string)+" must be listed in items.required")
				}
			}
		}
	}
	for name, v := range props(node) {
		if sub, ok := v.(map[string]interface{}); ok {
			listMapKeyProblems(path+"."+name, sub, problems)
		}
	}
	if items, ok := node["items"].(map[string]interface{}); ok {
		listMapKeyProblems(path+"[]", items, problems)
	}
}

func TestCRDSchemasMatchGoTypes(t *testing.T) {
	schemas := loadCRDSchemas(t)
	for kind, types := range crdKinds {
		root, ok := schemas[kind]
		if !ok {
			t.Errorf("%s: no CRD file under %s", kind, crdDir)
			continue
		}
		var problems []string
		top := props(root)
		spec, _ := top["spec"].(map[string]interface{})
		status, _ := top["status"].(map[string]interface{})
		walk(kind+".spec", types[0], spec, &problems)
		walk(kind+".status", types[1], status, &problems)
		listMapKeyProblems(kind, root, &problems)
		sort.Strings(problems)
		for _, p := range problems {
			t.Error(p)
		}
	}
}

// TestEveryCRDFileIsCovered — a new CRD file without a crdKinds entry
// would silently skip the drift check.
func TestEveryCRDFileIsCovered(t *testing.T) {
	for kind := range loadCRDSchemas(t) {
		if _, ok := crdKinds[kind]; !ok {
			t.Errorf("CRD kind %s has no entry in crdKinds — add its Spec/Status types", kind)
		}
	}
}
